        "dua_jahdil_bala" to DuaText("Ağır Denemelerden Sığınmak", "Allah'ım, şiddetli fitneden, bedbahtlığa uğramaktan, kötü kaderden ve düşmanların kibrinden Sana sığınırım.", "Şiddetli denemelerden ve düşmanların övünmelerinden sığının.", "Peygamber ﷺ bu dört şeyden sığındı."),
        "dua_fitnat_ghina_faqr" to DuaText("Zenginlik ve Yoksulluk Denemelerinden Sığınmak", "Allah'ım, tembellikten, yaşlılıktan, günah ve borçtan, kabir fitnesi ve azabından, ateş fitnesi ve azabından, zenginlik fitnesinin şerrinden, fakirlik fitnesinden sana sığınırım.", "Kabir fitnelerinden, cehennemden, zenginlikten ve fakirlikten sığınmak (duanın bir kısmı).", "Peygamber'den kapsamlı bir sığınma duası ﷺ."),
